// 🔥 FIX: Helper che considera ANCHE gli stati di onboarding
function getDestinationByUser(user: any): string {
  const role = user?.role?.toUpperCase() || "";
  const status = user?.status?.toUpperCase() || "ACTIVE";
  const isProprietario = ["PROPRIETARIO", "OWNER", "CLIENTE"].includes(role);

  // ✅ Se proprietario in onboarding, vai al passo corretto
  // Nuovo flusso: Registrazione → Billing (Step 1) → Contratto (Step 2) → Approvazione
  // NOTA: Non toccare utenti ACTIVE — alcuni vecchi utenti non hanno i campi booleani
  if (isProprietario && status !== "ACTIVE") {
    if (status === "PENDING_BILLING" || (!user?.billingCompleted && !user?.contractAccepted)) {
      return "/complete-billing";
    }
    if (status === "PENDING_CONTRACT" || (user?.billingCompleted && user?.contractAccepted === false)) {
      return "/accept-contract";
    }
    if (status === "PENDING_APPROVAL") {
      return "/pending-approval";
    }
  }

  // Utente attivo, vai alla dashboard del ruolo
  if (role === "ADMIN") return "/dashboard";
  if (isProprietario) return "/proprietario/calendario/pulizie";
  if (["OPERATORE_PULIZIE", "OPERATORE", "OPERATOR"].includes(role)) return "/operatore";
  if (role === "RIDER") return "/rider";
  return "/dashboard";
}

// Asset logo (icona + wordmark) — stessi dello splash, così login → splash è un flusso unico
const LOGO_SRC = 'data:image/png;base64,';
const WORD_SRC = 'data:image/png;base64,';

const rand = (a: number, b: number) => a + Math.random() * (b - a);

// Loading Screen - SOLO durante login attivo.
// 🎬 È il "primo fotogramma" dello splash: stesso gradiente, stesso logo,
// bolle già in movimento → nessuno stacco visivo quando arriva /welcome.
function LoadingScreen() {
  const bubbles = useMemo(
    () =>
      Array.from({ length: 18 }, () => ({
        size: rand(10, 40), left: rand(0, 100), bottom: rand(-10, -2),
        wob: rand(-24, 24), dur: rand(7, 14), delay: -rand(0, 14),
      })),
    []
  );
  const sparks = useMemo(
    () =>
      Array.from({ length: 14 }, () => ({
        size: rand(8, 16), left: rand(3, 97), top: rand(6, 92),
        dur: rand(1.6, 3.2), delay: -rand(0, 3),
      })),
    []
  );

  return (
    <div className="lsplash">
      <div className="lbg">
        {bubbles.map((b, i) => (
          <div key={`b${i}`} className="lbubble" style={{
            width: b.size, height: b.size, left: `${b.left}%`, bottom: `${b.bottom}%`,
            animationDuration: `${b.dur}s`, animationDelay: `${b.delay}s`,
            '--wob': `${b.wob}px`,
          } as CSSProperties} />
        ))}
        {sparks.map((s, i) => (
          <div key={`s${i}`} className="lspark" style={{
            width: s.size, height: s.size, left: `${s.left}%`, top: `${s.top}%`,
            animationDuration: `${s.dur}s`, animationDelay: `${s.delay}s`,
          }} />
        ))}
      </div>

      <div className="lcenter">
        <img className="llogo" src={LOGO_SRC} alt="CleaningApp" />
        <img className="lword" src={WORD_SRC} alt="Puliziacasevacanze.it" />
        <p className="ltext">Accesso in corso...</p>
        <div className="ldots"><i /><i /><i /></div>
      </div>

      <style jsx>{`
        .lsplash {
          position: fixed; inset: 0; z-index: 9999; overflow: hidden;
          display: flex; align-items: center; justify-content: center;
          background: linear-gradient(180deg, #63cef2 0%, #3aa9e0 50%, #2a83c8 100%);
          font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
        }
        .lbg { position: absolute; inset: 0; z-index: 1; overflow: hidden; }
        .lbubble { position: absolute; border-radius: 50%; border: 1px solid rgba(255,255,255,.4);
          background: radial-gradient(circle at 32% 28%, rgba(255,255,255,.95), rgba(255,255,255,.12) 42%, rgba(255,255,255,0) 64%);
          animation: lbubbleUp linear infinite; }
        @keyframes lbubbleUp { 0% { transform: translate(0,0); opacity: 0; } 8% { opacity: .9; }
          50% { transform: translate(var(--wob,14px), -58vh); } 90% { opacity: .9; } 100% { transform: translate(0,-116vh); opacity: 0; } }
        .lspark { position: absolute; color: #fff; background: currentColor;
          clip-path: polygon(50% 0,60% 40%,100% 50%,60% 60%,50% 100%,40% 60%,0 50%,40% 40%);
          filter: drop-shadow(0 0 6px rgba(255,255,255,.7)); animation: lsparkPop ease-in-out infinite; }
        @keyframes lsparkPop { 0%,100% { transform: scale(0) rotate(0); opacity: 0; } 50% { transform: scale(1) rotate(35deg); opacity: 1; } }

        .lcenter { position: relative; z-index: 5; display: flex; flex-direction: column; align-items: center; text-align: center; }
        .llogo { width: 150px; height: auto; display: block; filter: drop-shadow(0 14px 30px rgba(0,15,40,.4)); animation: llogoin .6s cubic-bezier(.22,1,.36,1) both; }
        @keyframes llogoin { 0% { opacity: 0; transform: scale(.7); } 100% { opacity: 1; transform: scale(1); } }
        .lword { width: 200px; height: auto; display: block; margin-top: 4px; filter: drop-shadow(0 4px 14px rgba(0,15,40,.35)); animation: lfade .6s ease-out .15s both; }
        .ltext { color: rgba(255,255,255,.8); font-size: 17px; font-weight: 600; margin: 28px 0 0; animation: lfade .6s ease-out .25s both; }
        .ldots { display: flex; gap: 9px; justify-content: center; margin-top: 16px; animation: lfade .6s ease-out .3s both; }
        .ldots i { width: 8px; height: 8px; border-radius: 50%; background: rgba(255,255,255,.8); animation: lblink 1.4s infinite; }
        .ldots i:nth-child(2) { animation-delay: .2s; } .ldots i:nth-child(3) { animation-delay: .4s; }
        @keyframes lfade { 0% { opacity: 0; transform: translateY(12px); } 100% { opacity: 1; transform: translateY(0); } }
        @keyframes lblink { 0%,80%,100% { opacity: .3; transform: scale(.8); } 40% { opacity: 1; transform: scale(1); } }
      `}</style>
    </div>
  );
}

